    if disabled != 0 {
        return Err("账号已停用".into());
    }
    let token = issue_session(id, device_id)?;
    db::audit(&username, "auth.login", device_id, "邮箱验证码");
    Ok((
        User {
            id,
            username,
            role,
            display_name,
            disabled: false,
        },
        token,
    ))
}
