        for _ in 0..5 {
            mail::CodeRequest::prepare(email, purpose, "")?.deliver(|_, _, _| Ok(()))?;
            db::open_db()?.execute("UPDATE login_attempts SET last_at=?1 WHERE scope='"'email' AND key=?2\",
                rusqlite::params"'![db::now() - 61, email]).map_err(|e| e.to_string())?;
        }
